15	  const navigate = useNavigate();
16	
17	  const campaignQuery = useQuery({
18	    queryKey: ['campaign', id],
19	    queryFn: () => request<Campaign>(`/api/campaigns/${id}`),
20	  });
21	
22	  const statsQuery = useQuery({
23	    queryKey: ['stats', id],
24	    queryFn: () => request<Stats>(`/api/stats/${id}`),
25	    refetchInterval: 2000,
26	  });
27	
28	  // Tracks which fetched campaign the edit form's fields currently reflect,
29	  // so they re-sync whenever the query returns a genuinely new object (first
30	  // load, a save, or another action's refetch) without needing an effect —
31	  // setting state during render like this is React's documented pattern for
32	  // "adjust state when a prop/query result changes".
33	  const [syncedCampaign, setSyncedCampaign] = useState<Campaign | null>(null);
34	  const [budgetDelta, setBudgetDelta] = useState('0');
35	  const [startDate, setStartDate] = useState('');
36	  const [endDate, setEndDate] = useState('');
37	
38	  if (campaignQuery.data && campaignQuery.data !== syncedCampaign) {
39	    setSyncedCampaign(campaignQuery.data);
40	    setBudgetDelta('0');
41	    setStartDate(toDatetimeLocalValue(new Date(campaignQuery.data.start_date)));
42	    setEndDate(toDatetimeLocalValue(new Date(campaignQuery.data.end_date)));
43	  }
44	
45	  function invalidateDetail() {
46	    queryClient.invalidateQueries({ queryKey: ['campaign', id] });
47	    queryClient.invalidateQueries({ queryKey: ['stats', id] });
48	  }
49	
50	  const edit = useMutation({
51	    mutationFn: (input: UpdateCampaignInput) =>
52	      request<Campaign>(`/api/campaigns/${id}`, { method: 'PATCH', body: input }),
53	    onSuccess: invalidateDetail,
54	  });
55	
56	  const pause = useMutation({
57	    mutationFn: () => request<Campaign>(`/api/campaigns/${id}/pause`, { method: 'POST' }),
58	    onSuccess: invalidateDetail,
59	  });
60	
61	  const resume = useMutation({
62	    mutationFn: () => request<Campaign>(`/api/campaigns/${id}/resume`, { method: 'POST' }),
63	    onSuccess: invalidateDetail,
64	  });
65	
66	  const end = useMutation({
67	    mutationFn: () => request<Campaign>(`/api/campaigns/${id}/end`, { method: 'POST' }),
68	    onSuccess: invalidateDetail,
69	  });
70	
71	  const del = useMutation({
72	    mutationFn: () => request<void>(`/api/campaigns/${id}`, { method: 'DELETE' }),
73	    onSuccess: () => {
74	      queryClient.invalidateQueries({ queryKey: ['campaigns'] });
75	      navigate('/');
76	    },
