package campaign

import (
	"context"
	"errors"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/jackc/pgx/v5"

	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/httpx"
)

type Service struct {
	repo *Repository
}

func NewService(repo *Repository) *Service {
	return &Service{repo: repo}
}

func (s *Service) Create(ctx context.Context, in CreateInput) (Campaign, error) {
	title := strings.TrimSpace(in.Title)
	if title == "" {
		return Campaign{}, httpx.Invalid("title is required")
	}
	if utf8.RuneCountInString(title) > 200 {
		return Campaign{}, httpx.Invalid("title must be at most 200 characters")
	}

	budget, err := strconv.ParseInt(string(in.Budget), 10, 64)
	if err != nil || budget < 1 {
		return Campaign{}, httpx.Invalid("budget must be a whole number >= 1")
	}

	// A missing/null JSON date decodes to time.Time's zero value (0001-01-01),
	// not an error, so it must be checked explicitly — otherwise an omitted
	// start_date passes both After() checks below (zero time is before any
	// real end_date, and any real end_date is after "now").
	if in.StartDate.IsZero() {
		return Campaign{}, httpx.Invalid("start_date is required")
	}
	if in.EndDate.IsZero() {
		return Campaign{}, httpx.Invalid("end_date is required")
	}

	if !in.EndDate.After(in.StartDate) {
		return Campaign{}, httpx.Invalid("end_date must be after start_date")
	}
	if !in.EndDate.After(time.Now()) {
		return Campaign{}, httpx.Invalid("end_date must be in the future")
	}

	return s.repo.Create(ctx, Campaign{
		Title:     title,
		Budget:    budget,
		StartDate: in.StartDate.UTC(),
		EndDate:   in.EndDate.UTC(),
	})
}

func (s *Service) List(ctx context.Context) ([]Campaign, error) {
	return s.repo.List(ctx)
}

func (s *Service) Get(ctx context.Context, id int64) (Campaign, error) {
	c, err := s.repo.GetByID(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return Campaign{}, httpx.NotFound("campaign not found")
	}
	if err != nil {
		return Campaign{}, err
	}
	return c, nil
}

func (s *Service) Update(ctx context.Context, id int64, in UpdateInput) (Campaign, error) {
	current, err := s.repo.GetByID(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return Campaign{}, httpx.NotFound("campaign not found")
	}
	if err != nil {
		return Campaign{}, err
	}

	if current.Status == StatusCompleted {
		return Campaign{}, httpx.Conflict("completed campaigns cannot be edited")
	}

	datesTouched := in.StartDate != nil || in.EndDate != nil
	if datesTouched && current.Status != StatusPaused {
		return Campaign{}, httpx.Conflict("dates can only be changed while the campaign is paused")
	}

	var newTitle *string
	if in.Title != nil {
		title := strings.TrimSpace(*in.Title)
		if title == "" {
			return Campaign{}, httpx.Invalid("title is required")
		}
		if utf8.RuneCountInString(title) > 200 {
			return Campaign{}, httpx.Invalid("title must be at most 200 characters")
		}
		newTitle = &title
	}

	var newBudget *int64
	if in.Budget != nil {
		budget, err := strconv.ParseInt(string(*in.Budget), 10, 64)
		if err != nil || budget < 1 {
			return Campaign{}, httpx.Invalid("budget must be a whole number >= 1")
		}
		// Comparing against the campaign's current state (spent), not a
		// property of the value alone, so this is a conflict (409) like the
		// completed/dates-while-active checks above, not an input error (400).
		if budget < current.Spent {
			return Campaign{}, httpx.Conflict("budget cannot be lower than spent")
		}
		newBudget = &budget
	}

	var newStart, newEnd *time.Time
	if datesTouched {
		effectiveStart := current.StartDate
		if in.StartDate != nil {
			if in.StartDate.IsZero() {
				return Campaign{}, httpx.Invalid("start_date cannot be empty")
			}
			effectiveStart = in.StartDate.UTC()
			newStart = &effectiveStart
		}
		effectiveEnd := current.EndDate
		if in.EndDate != nil {
			if in.EndDate.IsZero() {
				return Campaign{}, httpx.Invalid("end_date cannot be empty")
			}
			effectiveEnd = in.EndDate.UTC()
			newEnd = &effectiveEnd
		}
		if !effectiveEnd.After(effectiveStart) {
			return Campaign{}, httpx.Invalid("end_date must be after start_date")
		}
		if !effectiveEnd.After(time.Now()) {
			return Campaign{}, httpx.Invalid("end_date must be in the future")
		}
	}

	updated, err := s.repo.Update(ctx, id, newTitle, newBudget, newStart, newEnd)
	if errors.Is(err, pgx.ErrNoRows) {
		return Campaign{}, s.classifyUpdateConflict(ctx, id,
			conflictCheck{func(c Campaign) bool { return c.Status == StatusCompleted }, "completed campaigns cannot be edited"},
			conflictCheck{func(c Campaign) bool { return datesTouched && c.Status != StatusPaused }, "dates can only be changed while the campaign is paused"},
			conflictCheck{func(c Campaign) bool { return newBudget != nil && *newBudget < c.Spent }, "budget cannot be lower than spent"},
		)
	}
	if err != nil {
		return Campaign{}, err
	}
	return updated, nil
}

type conflictCheck struct {
	failed  func(Campaign) bool
	message string
}

// classifyUpdateConflict explains why a conditional UPDATE (Update's PATCH,
// or the impression endpoint's Deduct) matched zero rows: re-reads the row
// and returns 404 if it's missing/deleted, otherwise runs the caller-supplied
// checks in order and returns the first one whose condition still holds as a
// 409 — falling back to a generic conflict message if none match (only
// reachable if the row changed again between the original write attempt and
// this re-read).
func (s *Service) classifyUpdateConflict(ctx context.Context, id int64, checks ...conflictCheck) error {
	current, err := s.repo.GetByID(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return httpx.NotFound("campaign not found")
	}
	if err != nil {
		return err
	}
	for _, check := range checks {
		if check.failed(current) {
			return httpx.Conflict(check.message)
		}
	}
	return httpx.Conflict("campaign was modified concurrently, please retry")
}

func (s *Service) Delete(ctx context.Context, id int64) error {
	err := s.repo.SoftDelete(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return httpx.NotFound("campaign not found")
	}
	return err
}

func (s *Service) Pause(ctx context.Context, id int64) (Campaign, error) {
	c, err := s.repo.Pause(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return Campaign{}, s.classifyUpdateConflict(ctx, id,
			conflictCheck{func(c Campaign) bool { return c.Status != StatusActive }, "campaign is not active"},
		)
	}
	if err != nil {
		return Campaign{}, err
	}
	return c, nil
}

func (s *Service) Resume(ctx context.Context, id int64) (Campaign, error) {
	c, err := s.repo.Resume(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return Campaign{}, s.classifyUpdateConflict(ctx, id,
			conflictCheck{func(c Campaign) bool { return c.Status != StatusPaused }, "campaign is not paused"},
			conflictCheck{func(c Campaign) bool { return c.Spent >= c.Budget }, "no budget left"},
			conflictCheck{func(c Campaign) bool { return !c.EndDate.After(time.Now()) }, "end date has passed"},
		)
	}
	if err != nil {
		return Campaign{}, err
	}
	return c, nil
}

func (s *Service) End(ctx context.Context, id int64) (Campaign, error) {
	c, err := s.repo.End(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return Campaign{}, s.classifyUpdateConflict(ctx, id,
			conflictCheck{func(c Campaign) bool { return c.Status == StatusCompleted }, "campaign is already completed"},
		)
	}
	if err != nil {
		return Campaign{}, err
	}
	return c, nil
}

func (s *Service) Stats(ctx context.Context, id int64) (Stats, error) {
	c, err := s.repo.GetByID(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		return Stats{}, httpx.NotFound("campaign not found")
	}
	if err != nil {
		return Stats{}, err
	}
	return c.Stats(), nil
}

func (s *Service) RecordImpression(ctx context.Context, id int64) (Campaign, error) {
	c, err := s.repo.Deduct(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) {
		now := time.Now()
		return Campaign{}, s.classifyUpdateConflict(ctx, id,
			conflictCheck{func(c Campaign) bool { return c.Status != StatusActive }, "campaign is not active"},
			conflictCheck{func(c Campaign) bool { return now.Before(c.StartDate) }, "campaign has not started yet"},
			conflictCheck{func(c Campaign) bool { return !now.Before(c.EndDate) }, "campaign has ended"},
			conflictCheck{func(c Campaign) bool { return c.Spent >= c.Budget }, "campaign budget is exhausted"},
		)
	}
	if err != nil {
		return Campaign{}, err
	}
	return c, nil
}

package campaign

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

type Repository struct {
	pool *pgxpool.Pool
}

func NewRepository(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool}
}

const campaignColumns = "id, title, budget, spent, status, start_date, end_date, created_at, updated_at"

func (r *Repository) Create(ctx context.Context, c Campaign) (Campaign, error) {
	query := `
		INSERT INTO campaigns (title, budget, start_date, end_date)
		VALUES ($1, $2, $3, $4)
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, c.Title, c.Budget, c.StartDate, c.EndDate).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

func (r *Repository) List(ctx context.Context) ([]Campaign, error) {
	query := `
		SELECT ` + campaignColumns + `
		FROM campaigns
		WHERE deleted_at IS NULL
		ORDER BY created_at DESC`

	rows, err := r.pool.Query(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	campaigns := []Campaign{} // non-nil so a zero-row result marshals to [] not null
	for rows.Next() {
		var c Campaign
		if err := rows.Scan(
			&c.ID, &c.Title, &c.Budget, &c.Spent, &c.Status,
			&c.StartDate, &c.EndDate, &c.CreatedAt, &c.UpdatedAt,
		); err != nil {
			return nil, err
		}
		campaigns = append(campaigns, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return campaigns, nil
}

func (r *Repository) GetByID(ctx context.Context, id int64) (Campaign, error) {
	query := `
		SELECT ` + campaignColumns + `
		FROM campaigns
		WHERE id = $1 AND deleted_at IS NULL`

	var c Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&c.ID, &c.Title, &c.Budget, &c.Spent, &c.Status,
		&c.StartDate, &c.EndDate, &c.CreatedAt, &c.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return c, nil
}

// Update applies a partial update, using COALESCE so an absent (nil) field
// keeps the column's current value. Both invariants below are enforced as
// WHERE conditions rather than checked beforehand in Go, so they're evaluated
// by Postgres atomically against the current row under lock as part of this
// single statement — race-safe across multiple backend instances without any
// extra locking on our side:
//   - spent <= COALESCE(budget, budget): a no-op when budget isn't being
//     changed (spent <= budget already holds via the CHECK constraint), and
//     the real budget-decrease-vs-spent guard when it is.
//   - dates only touchable while paused: vacuously true when neither date
//     param is set, otherwise requires status = 'paused'.
//
// Zero matching rows surfaces as pgx.ErrNoRows via Scan, same as GetByID.
func (r *Repository) Update(ctx context.Context, id int64, title *string, budget *int64, startDate, endDate *time.Time) (Campaign, error) {
	// Params are explicitly cast (::text/::bigint/::timestamptz) because when
	// every optional field but one is nil, Postgres can't always infer a
	// placeholder's type from COALESCE/IS NULL context alone and rejects the
	// query with "could not determine data type of parameter" (42P08).
	query := `
		UPDATE campaigns
		SET
			title      = COALESCE($2::text, title),
			budget     = COALESCE($3::bigint, budget),
			start_date = COALESCE($4::timestamptz, start_date),
			end_date   = COALESCE($5::timestamptz, end_date),
			updated_at = now()
		WHERE id = $1
			AND deleted_at IS NULL
			AND status <> 'completed'
			AND spent <= COALESCE($3::bigint, budget)
			AND (($4::timestamptz IS NULL AND $5::timestamptz IS NULL) OR status = 'paused')
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id, title, budget, startDate, endDate).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

// SoftDelete never issues a DELETE statement — it sets deleted_at, and every
// query elsewhere filters deleted_at IS NULL. No status restriction: any
// non-deleted campaign, regardless of status, can be soft-deleted.
func (r *Repository) SoftDelete(ctx context.Context, id int64) error {
	query := `
		UPDATE campaigns
		SET deleted_at = now(), updated_at = now()
		WHERE id = $1 AND deleted_at IS NULL
		RETURNING id`

	var returnedID int64
	return r.pool.QueryRow(ctx, query, id).Scan(&returnedID)
}

// Pause is the same conditional-UPDATE idiom as Update/Deduct: the WHERE
// clause is the sole enforcement mechanism, so zero matching rows surfaces
// as pgx.ErrNoRows and gets disambiguated by classifyUpdateConflict.
func (r *Repository) Pause(ctx context.Context, id int64) (Campaign, error) {
	query := `
		UPDATE campaigns
		SET status = 'paused', updated_at = now()
		WHERE id = $1 AND deleted_at IS NULL AND status = 'active'
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

// Resume: spent < budget and end_date > now() are evaluated by Postgres
// atomically against the current row as part of this one statement, so a
// concurrent impression exhausting the budget at the same instant can't
// race past this check — whichever statement runs first wins, and the other
// correctly sees the post-write state.
func (r *Repository) Resume(ctx context.Context, id int64) (Campaign, error) {
	query := `
		UPDATE campaigns
		SET status = 'active', updated_at = now()
		WHERE id = $1
			AND deleted_at IS NULL
			AND status = 'paused'
			AND spent < budget
			AND end_date > now()
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

// End works from either 'active' or 'paused' — only 'completed' blocks it.
func (r *Repository) End(ctx context.Context, id int64) (Campaign, error) {
	query := `
		UPDATE campaigns
		SET status = 'completed', updated_at = now()
		WHERE id = $1 AND deleted_at IS NULL AND status <> 'completed'
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

// CompletePastEndDate marks every active/paused campaign whose end_date has
// passed as completed. This is a catch-up sweep, not a correctness
// mechanism — Deduct and Resume already check dates themselves — so a
// missed or delayed sweep can't let an impression through past end_date.
func (r *Repository) CompletePastEndDate(ctx context.Context) (int64, error) {
	query := `
		UPDATE campaigns
		SET status = 'completed', updated_at = now()
		WHERE deleted_at IS NULL
			AND status IN ('active', 'paused')
			AND end_date <= now()`

	tag, err := r.pool.Exec(ctx, query)
	if err != nil {
		return 0, err
	}
	return tag.RowsAffected(), nil
}

// Deduct atomically records one impression: increments spent by 1 and, if
// this deduction exhausts the budget, flips status to 'paused' in the same
// statement — no separate transition step, so no window where a concurrent
// call could sneak in between "deduct" and "pause". The WHERE clause is the
// sole correctness mechanism, evaluated by Postgres against the current row
// under lock as part of this one statement, so it's race-safe across
// multiple backend instances without any extra locking on our side.
func (r *Repository) Deduct(ctx context.Context, id int64) (Campaign, error) {
	query := `
		UPDATE campaigns
		SET
			spent  = spent + 1,
			status = CASE WHEN spent + 1 >= budget THEN 'paused' ELSE status END,
			updated_at = now()
		WHERE id = $1
			AND deleted_at IS NULL
			AND status = 'active'
			AND start_date <= now()
			AND end_date > now()
			AND spent < budget
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

package campaign

import (
	"encoding/json"
	"time"
)

const (
	StatusActive    = "active"
	StatusPaused    = "paused"
	StatusCompleted = "completed"
)

type Campaign struct {
	ID        int64     `json:"id"`
	Title     string    `json:"title"`
	Budget    int64     `json:"budget"`
	Spent     int64     `json:"spent"`
	Status    string    `json:"status"`
	StartDate time.Time `json:"start_date"`
	EndDate   time.Time `json:"end_date"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// MarshalJSON adds a computed "remaining" field. Remaining budget is never
// stored (budget - spent), so it's derived here rather than on the struct.
func (c Campaign) MarshalJSON() ([]byte, error) {
	type Alias Campaign // defined type, not an alias — drops MarshalJSON so this doesn't recurse

	// pgx returns scanned timestamps in the driver/host's local Location; the
	// instant is correct but json's RFC3339 output would print that offset
	// instead of "Z". Normalize to UTC here so every response is UTC.
	c.StartDate = c.StartDate.UTC()
	c.EndDate = c.EndDate.UTC()
	c.CreatedAt = c.CreatedAt.UTC()
	c.UpdatedAt = c.UpdatedAt.UTC()

	return json.Marshal(struct {
		Alias
		Remaining int64 `json:"remaining"`
	}{
		Alias:     Alias(c),
		Remaining: c.Budget - c.Spent,
	})
}

type CreateInput struct {
	Title     string      `json:"title"`
	Budget    json.Number `json:"budget"`
	StartDate time.Time   `json:"start_date"`
	EndDate   time.Time   `json:"end_date"`
}

// UpdateInput uses pointers so "field absent" (nil) is distinguishable from
// "field sent" — required for PATCH's partial-update semantics.
type UpdateInput struct {
	Title     *string      `json:"title"`
	Budget    *json.Number `json:"budget"`
	StartDate *time.Time   `json:"start_date"`
	EndDate   *time.Time   `json:"end_date"`
}

// Stats is the smaller /stats/{id} shape (no title/dates/timestamps).
type Stats struct {
	Impressions int64  `json:"impressions"`
	Spent       int64  `json:"spent"`
	Remaining   int64  `json:"remaining"`
	Budget      int64  `json:"budget"`
	Status      string `json:"status"`
}

// Stats derives impressions from spent — impressions aren't stored as a
// separate counter, since 1 impression always equals 1 unit spent.
func (c Campaign) Stats() Stats {
	return Stats{
		Impressions: c.Spent,
		Spent:       c.Spent,
		Remaining:   c.Budget - c.Spent,
		Budget:      c.Budget,
		Status:      c.Status,
	}
}

